script:
frappe.listview_settings['Vendor Purchase Order'].onload = function(listview) {
    if (frappe.user.has_role('PO Generator') || frappe.user.has_role('System Manager')) {
        listview.page.add_inner_button('New External PO', function() {
            frappe.new_doc('Vendor Purchase Order', {po_type: 'Vendor PO'});
        });
        listview.page.add_inner_button('New Internal PO', function() {
            frappe.new_doc('Vendor Purchase Order', {
                po_type: 'Internal PO',
                vendor: 'Sarveksha Realty and Inframine LLP',
                company: ''
            });
        });
    }
};
